diff --git a/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js b/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js
index 773aa59..b0888e8 100644
--- a/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js
+++ b/packages/svelte/src/compiler/phases/2-analyze/visitors/Attribute.js
@@ -181,6 +181,19 @@ function get_delegated_event(event_name, handler, context) {
 		if (scope.get(`$${reference}`)?.kind === 'store_sub') return unhoisted;

 		const binding = scope.get(reference);
+
+		// `scope.references` contains references that have bubbled up from nested scopes,
+		// so this reference could have been resolved to a binding declared inside the
+		// function itself (e.g. shadowing an outer name) — in that case it's irrelevant
+		if (
+			binding !== null &&
+			!scope
+				.references.get(reference)!
+				.some(({ node }) => binding.references.some((r) => r.node === node))
+		) {
+			continue;
+		}
+
 		const local_binding = context.state.scope.get(reference);

 		// if the function access a snippet that can't be hoisted we bail out
